    if (dupCount > 0) { orig -= 10; warnings.push('Duplicate topic title detected across existing catalog.'); }
    var links = 15;
    var ux = 10;
    var conv = 10;
    var total = Math.max(0, orig + intent + tech + links + ux + conv);
    return { total: total, orig: orig, intent: intent, tech: tech, links: links, ux: ux, conv: conv, warnings: warnings };
